// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
        if (!ok) {
            assertTrue(address(c).code.length > 0);
        } else {
            assertTrue(address(c).code.length == 0);
        }
    }
}
